MathJax.Hub.Queue(["Typeset",MathJax.Hub]);

let delta =xscale/(n-1);
let xi=-xscale/2;
for (let i = 0; i < n; i++) {
  xvec[i]=xi;
  let yi=getMultiSlitAmp(xi);
  yvec[i]=yi*yi;
  let ui=getSingleSlitAmp(xi);
  uvec[i]=ui*ui;
  xi+=delta;
}
var newColors=intensityToRGBScale(yvec);
for (let i = 0; i < n; i++) {
  colors[i]=newColors[i];
}
layout = {
  margin: {
    l: 0,
    r: 0,
    b: 0,
    t: 0
  } ,
  xaxis: {
    visible: false
  } ,
  yaxis: {
    visible: false
  } ,
  bargap: 0,
  plot_bgcolor: '#000000',
  //paper_bgcolor:"white",
  width: width, // Set fixed width
  height: height, // Set fixed height
  showlegend: false, // Hide the legend
  yaxis: { range: [0, 1]}
} ;

intensityTrace={
    x: xvec,
    y: yvec,
    mode: "lines",
    line: {
      color: "red",
      width: 2
    }
}

envelopeTrace={
    x: xvec,
    y: uvec,
    mode: "lines",
    line: {
      color: "purple",
      width: 2,
      shape: 'spline'
    }
} 

traces =[ {
    x: xvec,
    y: unitvec,
    type: 'bar',
    marker:{color:colors}
  },
  intensityTrace,
  envelopeTrace
]

// Create plot
Plotly.newPlot("plotlyPanel",traces, layout);

