function intensityToRGBScale(intensities) {
  const normalizedValues = intensities.map(value => value / Math.max(...intensities));
  vals=lightPalette(lambda);
  r=vals[0];
  g=vals[1];
  b=vals[2];
  //return normalizedValues.map(value => `rgb(${Math.floor(value * r)}, ${Math.floor(value * g)}, ${Math.floor(value * b)})`);
  return normalizedValues.map(value => `rgb(${Math.floor(Math.sqrt(value) * r)}, ${Math.floor(Math.sqrt(value) * g)}, ${Math.floor(Math.sqrt(value) * b)})`);
}

function getSingleSlitAmp(x){
  alpha=Math.PI*x*D/L/lambda;
  if(alpha==0){
    return 1;
  }else{
    return Math.sin(alpha)/alpha;
  } 
}

function getMultiSlitAmp(x){
  if (N==1){
    return getSingleSlitAmp(x);
  }
  beta=Math.PI*x*d/L/lambda;
  return getSingleSlitAmp(x)*Math.sin(N*beta)/Math.sin(beta)/N;
}
const HSBToRGB = (h, s, b) => {
  s /= 100;
  b /= 100;
  const k = (n) => (n + h / 60) % 6;
  const f = (n) => b * (1 - s * Math.max(0, Math.min(k(n), 4 - k(n), 1)));
  return [255 * f(5), 255 * f(3), 255 * f(1)];
};

function lightPalette(wavelength) {
    var h=(-2.5*wavelength+1.625);
    var s=1;
    if(wavelength>=0.65){
      h=0;
      s=(1-wavelength)/0.35;
     }
    if(wavelength<=0.35){
      h=0.75;
      s=(wavelength/0.35);
    }
   return HSBToRGB(360*h, 100*s, 100);
}
function redrawTraces() {   // assumes xvec has not changed
  for (let i = 0; i < n; i++) {
    let xi=xvec[i];
    yi=getMultiSlitAmp(xi);
    yvec[i]=yi*yi;
    let ui=getSingleSlitAmp(xi);
    uvec[i]=ui*ui;
  }
  var newColors=intensityToRGBScale(yvec);
  for (let i = 0; i < n; i++) {
    colors[i]=newColors[i];
  }
  // Update the y trace with new data
  Plotly.restyle("plotlyPanel", 'y', [yvec], [1]); // 0 refers to the index of the trace
}

function showTraces(show){
  traces[1].visible=show;
  traces[2].visible=show;
  redrawTraces();
}
